def get_transcript(url, lang=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0543000" if __import__("os").path.isdir("./environment_mix/0543000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, http_status, ok, detail=None):
        # Optional observable dynamics: if request_logs collection exists in this store, append logs.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return
        ts = _now_iso()
        latency_ms = int(max(0, (time.time() - started) * 1000))
        rid = "rl_" + hashlib.sha256((ts + "|" + endpoint + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "timestamp": ts,
            "endpoint": endpoint,
            "credential_id": None,
            "http_status": int(http_status) if isinstance(http_status, int) else None,
            "ok": bool(ok),
            "latency_ms": latency_ms,
            "detail": detail,
        })
        _save("request_logs.json", logs)

    def _parse_video_id(u):
        u = u.strip()
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return None, None
        host = (p.netloc or "").lower()
        path = p.path or ""
        qs = urllib.parse.parse_qs(p.query or "")
        vid = None
        if "v" in qs and qs["v"]:
            vid = qs["v"][0]
        if vid is None and host.endswith("youtu.be"):
            cand = path.lstrip("/").split("/")[0]
            if cand:
                vid = cand
        # Very permissive acceptance but bounded by schema constraint.
        if not isinstance(vid, str):
            return None, None
        vid = vid.strip()
        if not vid or not (6 <= len(vid) <= 32):
            return None, None
        canon = "https://www.youtube.com/watch?v=" + vid
        return vid, canon

    # --- validation (input schema) ---
    if not isinstance(url, str) or not url.strip():
        _log("get_transcript", 400, False, "VALIDATION_ERROR url")
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string", field="url")
    if lang is None:
        lang = "en"
    if not isinstance(lang, str) or not lang.strip():
        _log("get_transcript", 400, False, "VALIDATION_ERROR lang")
        return _err("VALIDATION_ERROR", "lang must be a non-empty string", field="lang")
    if len(lang.strip()) > 16:
        _log("get_transcript", 400, False, "VALIDATION_ERROR lang length")
        return _err("VALIDATION_ERROR", "lang must be at most 16 characters", field="lang")
    if not re.fullmatch(r"[A-Za-z]{1,8}([_-][A-Za-z0-9]{1,8}){0,3}", lang.strip()):
        _log("get_transcript", 400, False, "VALIDATION_ERROR lang format")
        return _err("VALIDATION_ERROR", "lang must be a supported format like 'en' or 'en-US'", field="lang")

    requested_lang = lang
    normalized_lang = requested_lang.strip().lower().replace("_", "-")

    # --- MUST create transcript_requests row first ---
    reqs = _load("transcript_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    now = _now_iso()
    req_id = "ytrq_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
    req_row = {
        "id": req_id,
        "raw_url": url,
        "requested_lang": requested_lang,
        "normalized_lang": normalized_lang,
        "video_id": None,
        "status": "queued",
        "transcript_id": None,
        "served_from_cache": False,
        "error_code": None,
        "error_message": None,
        "http_status": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("transcript_requests.json", reqs)

    def _set_req_status(from_status, to_status, **fields):
        transitions = {
            "queued": ["running", "failed", "rate_limited"],
            "running": ["succeeded", "not_found", "no_transcript", "invalid_url", "failed", "rate_limited"],
            "succeeded": [],
            "not_found": [],
            "no_transcript": [],
            "invalid_url": [],
            "rate_limited": [],
            "failed": [],
        }
        all_reqs = _load("transcript_requests.json")
        if not isinstance(all_reqs, list):
            return _err("FAILED", "transcript_requests store is not a list")
        idx = next((i for i, r in enumerate(all_reqs) if isinstance(r, dict) and r.get("id") == req_id), None)
        if idx is None:
            return _err("NOT_FOUND", "transcript_request not found", id=req_id)
        cur = all_reqs[idx].get("status")
        if cur != from_status:
            # allow idempotent set if already in desired status
            if cur == to_status:
                return all_reqs[idx]
            return _err("INVALID_TRANSITION", "Cannot transition transcript_requests.status", from_status=cur, to_status=to_status)
        if to_status not in transitions.get(from_status, []):
            return _err("INVALID_TRANSITION", "Cannot transition transcript_requests.status", from_status=from_status, to_status=to_status)
        all_reqs[idx]["status"] = to_status
        all_reqs[idx]["updated_at"] = _now_iso()
        for k, v in fields.items():
            all_reqs[idx][k] = v
        _save("transcript_requests.json", all_reqs)
        return all_reqs[idx]

    def _patch_req(**fields):
        all_reqs = _load("transcript_requests.json")
        if not isinstance(all_reqs, list):
            return _err("FAILED", "transcript_requests store is not a list")
        idx = next((i for i, r in enumerate(all_reqs) if isinstance(r, dict) and r.get("id") == req_id), None)
        if idx is None:
            return _err("NOT_FOUND", "transcript_request not found", id=req_id)
        all_reqs[idx]["updated_at"] = _now_iso()
        for k, v in fields.items():
            all_reqs[idx][k] = v
        _save("transcript_requests.json", all_reqs)
        return all_reqs[idx]

    def _finalize_terminal(status, http_status=None, error_code=None, error_message=None, transcript_id=None, video_id=None, served_from_cache=False):
        dur = int(max(0, (time.time() - started) * 1000))
        # terminal statuses must come from running (or queued->rate_limited/failed already handled)
        cur_reqs = _load("transcript_requests.json")
        if not isinstance(cur_reqs, list):
            return _err("FAILED", "transcript_requests store is not a list")
        row = next((r for r in cur_reqs if isinstance(r, dict) and r.get("id") == req_id), None)
        if row is None:
            return _err("NOT_FOUND", "transcript_request not found", id=req_id)
        cur_status = row.get("status")
        terminal = status
        if cur_status == "queued":
            # must transition to running before any upstream attempt; but cached serves can go queued->running->succeeded
            res = _set_req_status("queued", "running")
            if isinstance(res, dict) and "error" in res:
                return res
            cur_status = "running"
        if cur_status == "running":
            res = _set_req_status("running", terminal,
                                  http_status=http_status,
                                  error_code=error_code,
                                  error_message=error_message,
                                  transcript_id=transcript_id,
                                  video_id=video_id,
                                  served_from_cache=bool(served_from_cache),
                                  duration_ms=dur)
            return res
        # already terminal; idempotently patch duration_ms if missing
        if row.get("duration_ms") is None:
            return _patch_req(duration_ms=dur)
        return row

    # --- URL parse / validate ---
    yt_vid, canonical_url = _parse_video_id(url)
    if yt_vid is None:
        # queued -> running -> invalid_url (per lifecycle)
        _set_req_status("queued", "running")
        _finalize_terminal("invalid_url", http_status=400, error_code="PARSE_URL_ERROR", error_message="Could not extract YouTube video id from url", video_id=None)
        _log("get_transcript", 400, False, "invalid_url")
        return _err("VALIDATION_ERROR", "Invalid YouTube URL: could not extract video id", error_code="PARSE_URL_ERROR")

    # --- upsert video and attach to request ---
    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []
    vid_row = next((v for v in videos if isinstance(v, dict) and v.get("youtube_video_id") == yt_vid), None)
    if vid_row is None:
        v_id = "ytv_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
        nowv = _now_iso()
        vid_row = {
            "id": v_id,
            "youtube_video_id": yt_vid,
            "canonical_url": canonical_url,
            "title": None,
            "channel_id": None,
            "created_at": nowv,
            "updated_at": nowv,
        }
        videos.append(vid_row)
        _save("videos.json", videos)
    else:
        # refresh canonical_url if missing/mismatched, update timestamp
        changed = False
        if isinstance(canonical_url, str) and canonical_url and vid_row.get("canonical_url") != canonical_url:
            vid_row["canonical_url"] = canonical_url
            changed = True
        if changed:
            vid_row["updated_at"] = _now_iso()
            _save("videos.json", videos)

    _patch_req(video_id=vid_row["id"])

    # --- cache lookup: active transcript exists for (video_id, normalized_lang) ---
    transcripts = _load("transcripts.json")
    if not isinstance(transcripts, list):
        transcripts = []
    active = next((t for t in transcripts
                   if isinstance(t, dict)
                   and t.get("video_id") == vid_row["id"]
                   and t.get("lang") == normalized_lang
                   and t.get("status") == "active"), None)
    if active is not None:
        # Must still obey request lifecycle: queued->running->succeeded
        _set_req_status("queued", "running")
        _finalize_terminal("succeeded", http_status=200, transcript_id=active["id"], video_id=vid_row["id"], served_from_cache=True)
        cues = _load("transcript_cues.json")
        if not isinstance(cues, list):
            cues = []
        cue_rows = [c for c in cues if isinstance(c, dict) and c.get("transcript_id") == active["id"]]
        cue_rows.sort(key=lambda r: (r.get("seq") if isinstance(r.get("seq"), int) else 10**9))
        _log("get_transcript", 200, True, "served_from_cache")
        return {
            "transcript_request_id": req_id,
            "served_from_cache": True,
            "video": vid_row,
            "transcript": active,
            "cues": cue_rows,
        }

    # --- No cached transcript: simulate upstream fetch (offline). Mark terminal not_found/no_transcript/failed. ---
    # We must transition queued -> running before "upstream access".
    r = _set_req_status("queued", "running")
    if isinstance(r, dict) and "error" in r:
        _log("get_transcript", 409, False, "transition error")
        return r

    # Offline backend: cannot fetch upstream. Choose a deterministic terminal state:
    # If video exists in YouTube id format but no transcript stored, return no_transcript (more specific than not_found).
    term = _finalize_terminal("no_transcript", http_status=404, error_code="YT_NO_CAPTIONS", error_message="No cached transcript available and upstream fetch is unavailable in offline mode.", video_id=vid_row["id"])
    if isinstance(term, dict) and "error" in term:
        _log("get_transcript", 500, False, "finalize error")
        return term
    _log("get_transcript", 404, False, "no_transcript_offline")

    # Read tools should return data not errors when possible; here transcript is absent, so return an empty transcript payload plus request record.
    return {
        "transcript_request_id": req_id,
        "served_from_cache": False,
        "video": vid_row,
        "transcript": None,
        "cues": [],
        "status": "no_transcript",
        "error_code": "YT_NO_CAPTIONS",
        "error_message": "No cached transcript available and upstream fetch is unavailable in offline mode.",
    }

def list_transcript_requests(status=None, video_id=None, youtube_video_id=None, normalized_lang=None, served_from_cache=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0543000" if __import__("os").path.isdir("./environment_mix/0543000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    valid_status = {"queued","running","succeeded","not_found","no_transcript","invalid_url","rate_limited","failed"}
    if status is not None:
        if not isinstance(status, str) or status not in valid_status:
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(valid_status))
    if video_id is not None and (not isinstance(video_id, str) or not video_id.strip()):
        return _err("VALIDATION_ERROR", "video_id must be a non-empty string", field="video_id")
    if youtube_video_id is not None and (not isinstance(youtube_video_id, str) or not youtube_video_id.strip()):
        return _err("VALIDATION_ERROR", "youtube_video_id must be a non-empty string", field="youtube_video_id")
    if normalized_lang is not None and (not isinstance(normalized_lang, str) or not normalized_lang.strip()):
        return _err("VALIDATION_ERROR", "normalized_lang must be a non-empty string", field="normalized_lang")
    if served_from_cache is not None and not isinstance(served_from_cache, bool):
        return _err("VALIDATION_ERROR", "served_from_cache must be a boolean", field="served_from_cache")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")

    # resolve youtube_video_id -> video_id if requested
    if youtube_video_id is not None:
        vids = _load("videos.json")
        vrow = next((v for v in vids if v.get("youtube_video_id") == youtube_video_id), None)
        if vrow is None:
            # valid filter, matches nothing
            return {
                "data": [],
                "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}
            }
        video_id = vrow.get("id")

    reqs = _load("transcript_requests.json")

    # order by created_at desc (ISO Z sorts lexicographically)
    reqs_sorted = sorted(reqs, key=lambda r: (r.get("created_at") or ""), reverse=True)

    # cursor is base64 encoded created_at + id
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===").decode("utf-8")
            c_created, c_id = raw.split("|", 1)
            # find position after this item in current ordering
            for i, r in enumerate(reqs_sorted):
                if (r.get("created_at") or "") == c_created and (r.get("id") or "") == c_id:
                    start = i + 1
                    break
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    def _match(r):
        if status is not None and r.get("status") != status: return False
        if video_id is not None and r.get("video_id") != video_id: return False
        if normalized_lang is not None and r.get("normalized_lang") != normalized_lang: return False
        if served_from_cache is not None and r.get("served_from_cache") != served_from_cache: return False
        return True

    filtered = [r for r in reqs_sorted if _match(r)]
    total = len(filtered)
    page = filtered[start:start+limit]
    has_more = start + limit < total
    next_cursor = None
    if has_more and page:
        last = page[-1]
        token = f"{last.get('created_at') or ''}|{last.get('id') or ''}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("ascii").rstrip("=")

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

def get_transcript_request(id, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0543000" if __import__("os").path.isdir("./environment_mix/0543000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, http_status, ok, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return
        ts = _now_iso()
        latency_ms = int(max(0, (time.time() - started) * 1000))
        rid = "rl_" + hashlib.sha256((ts + "|" + endpoint + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "timestamp": ts,
            "endpoint": endpoint,
            "credential_id": None,
            "http_status": int(http_status) if isinstance(http_status, int) else None,
            "ok": bool(ok),
            "latency_ms": latency_ms,
            "detail": detail,
        })
        _save("request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _log("get_transcript_request", 400, False, "VALIDATION_ERROR id")
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")

    # IMPORTANT: callers may mistakenly pass a videos.id or transcripts.id; try to resolve to the latest request for that entity.
    reqs = _load("transcript_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    row = next((r for r in reqs if isinstance(r, dict) and r.get("id") == id), None)

    if row is None:
        # Fallback mapping: if id is a videos.id, return most recent request for that video_id
        if id.startswith("ytv_"):
            candidates = [r for r in reqs if isinstance(r, dict) and r.get("video_id") == id]
            candidates.sort(key=lambda r: r.get("created_at") or "", reverse=True)
            row = candidates[0] if candidates else None
        elif id.startswith("ytt_"):
            candidates = [r for r in reqs if isinstance(r, dict) and r.get("transcript_id") == id]
            candidates.sort(key=lambda r: r.get("created_at") or "", reverse=True)
            row = candidates[0] if candidates else None

    if row is None:
        _log("get_transcript_request", 404, False, "NOT_FOUND")
        return _err("NOT_FOUND", "transcript_request not found", id=id)

    _log("get_transcript_request", 200, True, None)
    return {"transcript_request": row}

def create_transcript_request(url, lang=None, **_extra):
    import json, os, datetime, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0543000" if __import__("os").path.isdir("./environment_mix/0543000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string", field="url")
    if lang is None:
        lang = "en"
    if not isinstance(lang, str) or not lang.strip():
        return _err("VALIDATION_ERROR", "lang must be a non-empty string", field="lang")
    if len(lang.strip()) > 16:
        return _err("VALIDATION_ERROR", "lang must be at most 16 characters", field="lang")
    if not re.fullmatch(r"[A-Za-z]{2,8}([_-][A-Za-z0-9]{2,8}){0,3}", lang.strip()):
        return _err("VALIDATION_ERROR", "lang must be a supported format like 'en' or 'en-US'", field="lang")

    requested_lang = lang
    normalized_lang = requested_lang.strip().lower().replace("_", "-")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    reqs = _load("transcript_requests.json")
    req_id = "trq_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
    row = {
        "id": req_id,
        "raw_url": url,
        "requested_lang": requested_lang,
        "normalized_lang": normalized_lang,
        "video_id": None,
        "status": "queued",
        "transcript_id": None,
        "served_from_cache": False,
        "error_code": None,
        "error_message": None,
        "http_status": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(row)
    _save("transcript_requests.json", reqs)

    return {"transcript_request": row}

def list_transcripts(video_id=None, youtube_video_id=None, lang=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0543000" if __import__("os").path.isdir("./environment_mix/0543000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_lang(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s.strip().lower().replace("_", "-")
        return s2

    def _log(endpoint, status_code, ok, credential_id=None, detail=None, started=None):
        # Best-effort request log + rate/quota enforcement.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now_iso()
        latency_ms = None
        if started is not None:
            latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": "rl_" + hashlib.sha256((ts + "|" + endpoint + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "timestamp": ts,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "http_status": int(status_code) if isinstance(status_code, int) else None,
            "ok": bool(ok),
            "latency_ms": latency_ms,
            "detail": detail,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, started):
        # If limits collections are absent, treat as unlimited.
        rate_limits = _load("rate_limits.json")
        usage = _load("usage.json")
        logs = _load("request_logs.json")

        if not isinstance(rate_limits, list):
            rate_limits = []
        if not isinstance(usage, list):
            usage = []
        if not isinstance(logs, list):
            logs = []

        # Find a limit row that applies to this endpoint, else no limit.
        # Expected shapes (best-effort):
        # rate_limits: [{ "endpoint": "list_transcripts", "per_minute": 60, "per_day": 5000 }]
        # usage: [{ "date": "YYYY-MM-DD", "endpoint": "...", "count": N, "quota": M }]
        per_minute = None
        per_day = None
        for rl in rate_limits:
            if isinstance(rl, dict) and rl.get("endpoint") == endpoint:
                if isinstance(rl.get("per_minute"), int):
                    per_minute = rl["per_minute"]
                if isinstance(rl.get("per_day"), int):
                    per_day = rl["per_day"]
                break

        now = datetime.datetime.utcnow()
        if per_minute is not None:
            cutoff = now - datetime.timedelta(minutes=1)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if t >= cutoff:
                    cnt += 1
            if cnt >= per_minute:
                _log(endpoint, 429, False, detail="rate_limit_per_minute", started=started)
                return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

        if per_day is not None:
            today = now.date().isoformat()
            # Count today from logs.
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str) or not ts.startswith(today):
                    continue
                cnt += 1
            if cnt >= per_day:
                _log(endpoint, 429, False, detail="quota_per_day", started=started)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", http_status=429)

        return None

    started = time.time()
    endpoint = "list_transcripts"

    # Enforce any configured rate/quota limits.
    lim_err = _enforce_limits(endpoint, started)
    if lim_err:
        return lim_err

    # Ambient authentication: if there is any access-control store, select a combination that allows reads.
    # If none exists, authorize.
    access = _load("access.json")
    if isinstance(access, list) and access:
        allowed = any(isinstance(r, dict) and r.get("can_read_transcripts") is True for r in access)
        if not allowed:
            _log(endpoint, 401, False, detail="no_access_row_allows_read", started=started)
            return _err("UNAUTHORIZED", "Caller lacks access to list transcripts.", http_status=401)

    # Validate inputs
    if video_id is not None and not isinstance(video_id, str):
        _log(endpoint, 400, False, detail="bad_video_id_type", started=started)
        return _err("VALIDATION_ERROR", "video_id must be a string.")
    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        _log(endpoint, 400, False, detail="bad_youtube_video_id_type", started=started)
        return _err("VALIDATION_ERROR", "youtube_video_id must be a string.")
    if lang is not None and not isinstance(lang, str):
        _log(endpoint, 400, False, detail="bad_lang_type", started=started)
        return _err("VALIDATION_ERROR", "lang must be a string.")
    if status is not None:
        if not isinstance(status, str):
            _log(endpoint, 400, False, detail="bad_status_type", started=started)
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("active", "superseded", "deleted"):
            _log(endpoint, 400, False, detail="bad_status_value", started=started)
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["active", "superseded", "deleted"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(endpoint, 400, False, detail="bad_limit_type", started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        _log(endpoint, 400, False, detail="limit_out_of_range", started=started)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

    if cursor is not None and not isinstance(cursor, str):
        _log(endpoint, 400, False, detail="bad_cursor_type", started=started)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    norm_lang = _norm_lang(lang) if lang is not None else None
    if lang is not None:
        if norm_lang is None or len(norm_lang) == 0 or len(norm_lang) > 16:
            _log(endpoint, 400, False, detail="lang_invalid", started=started)
            return _err("VALIDATION_ERROR", "lang must be non-empty and at most 16 characters (after normalization).")

    # Resolve youtube_video_id -> internal video_id if needed
    vids = _load("videos.json")
    if not isinstance(vids, list):
        vids = []

    resolved_video_id = video_id
    if youtube_video_id is not None:
        # Find by youtube_video_id exact
        match = None
        for v in vids:
            if isinstance(v, dict) and v.get("youtube_video_id") == youtube_video_id:
                match = v
                break
        if match is None:
            # Filter matches nothing => empty result set.
            _log(endpoint, 200, True, detail="no_matching_video", started=started)
            return {
                "object": "list",
                "data": [],
                "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None},
            }
        resolved_video_id = match.get("id")

    # Cursor decoding
    # Cursor is base64url(json({"fetched_at": "...", "id": "..." }))
    after_fetched_at = None
    after_id = None
    if cursor:
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            cobj = json.loads(raw)
            if not isinstance(cobj, dict):
                raise ValueError("cursor not an object")
            after_fetched_at = cobj.get("fetched_at")
            after_id = cobj.get("id")
            if after_fetched_at is not None and not isinstance(after_fetched_at, str):
                raise ValueError("cursor fetched_at must be str")
            if after_id is not None and not isinstance(after_id, str):
                raise ValueError("cursor id must be str")
        except Exception:
            _log(endpoint, 400, False, detail="cursor_decode_failed", started=started)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    transcripts = _load("transcripts.json")
    if not isinstance(transcripts, list):
        transcripts = []

    # Filter
    rows = []
    for t in transcripts:
        if not isinstance(t, dict):
            continue
        if resolved_video_id is not None and t.get("video_id") != resolved_video_id:
            continue
        if norm_lang is not None:
            tlang = t.get("lang")
            if not isinstance(tlang, str) or _norm_lang(tlang) != norm_lang:
                continue
        if status is not None and t.get("status") != status:
            continue
        rows.append(t)

    def _key(t):
        fa = t.get("fetched_at")
        # Treat missing/invalid fetched_at as oldest
        try:
            dt = datetime.datetime.fromisoformat(str(fa).replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(t.get("id") or ""))

    # Sort by fetched_at desc, then id desc
    rows.sort(key=_key, reverse=True)

    # Apply cursor as "start after" (exclusive)
    if after_fetched_at is not None or after_id is not None:
        def _cursor_key():
            try:
                dtc = datetime.datetime.fromisoformat(str(after_fetched_at).replace("Z", "+00:00"))
            except Exception:
                dtc = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dtc, str(after_id or ""))
        ck = _cursor_key()
        filtered = []
        for t in rows:
            if _key(t) < ck:
                filtered.append(t)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"fetched_at": last.get("fetched_at"), "id": last.get("id")}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _log(endpoint, 200, True, detail="ok", started=started)
    return {
        "object": "list",
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def update_transcript(id, status=None, source=None, is_generated=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0543000" if __import__("os").path.isdir("./environment_mix/0543000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, http_status, ok, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return
        ts = _now_iso()
        latency_ms = int(max(0, (time.time() - started) * 1000))
        rid = "rl_" + hashlib.sha256((ts + "|" + endpoint + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "timestamp": ts,
            "endpoint": endpoint,
            "credential_id": None,
            "http_status": int(http_status) if isinstance(http_status, int) else None,
            "ok": bool(ok),
            "latency_ms": latency_ms,
            "detail": detail,
        })
        _save("request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _log("update_transcript", 400, False, "VALIDATION_ERROR id")
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")

    # If optional fields provided, validate types/enums
    allowed_status = {"active", "superseded", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("update_transcript", 400, False, "VALIDATION_ERROR status")
            return _err("VALIDATION_ERROR", "status must be one of: active, superseded, deleted", field="status")
    if source is not None:
        if not isinstance(source, str) or not source.strip():
            _log("update_transcript", 400, False, "VALIDATION_ERROR source")
            return _err("VALIDATION_ERROR", "source must be a non-empty string when provided", field="source")
        if len(source) > 64:
            _log("update_transcript", 400, False, "VALIDATION_ERROR source length")
            return _err("VALIDATION_ERROR", "source too long", field="source")
    if is_generated is not None and not isinstance(is_generated, bool):
        _log("update_transcript", 400, False, "VALIDATION_ERROR is_generated")
        return _err("VALIDATION_ERROR", "is_generated must be a boolean when provided", field="is_generated")

    transcripts = _load("transcripts.json")
    if not isinstance(transcripts, list):
        transcripts = []

    # IMPORTANT: audit shows callers may pass a videos.id here. If so, update the ACTIVE transcript for that video (any lang).
    t_idx = next((i for i, t in enumerate(transcripts) if isinstance(t, dict) and t.get("id") == id), None)
    if t_idx is None and id.startswith("ytv_"):
        # choose latest active transcript for that video
        candidates = [(i, t) for i, t in enumerate(transcripts)
                      if isinstance(t, dict) and t.get("video_id") == id and t.get("status") == "active"]
        if candidates:
            # prefer most recently updated
            candidates.sort(key=lambda it: (it[1].get("updated_at") or it[1].get("created_at") or ""), reverse=True)
            t_idx = candidates[0][0]

    if t_idx is None:
        _log("update_transcript", 404, False, "NOT_FOUND")
        return _err("NOT_FOUND", "Transcript not found for given id (expected transcript id like 'ytt_...' or a video id with an active transcript).", http_status=404, id=id)

    row = transcripts[t_idx]
    old_status = row.get("status")

    transitions = {
        "active": {"superseded", "deleted"},
        "superseded": {"deleted"},
        "deleted": set(),
    }

    if status is not None and status != old_status:
        if old_status not in transitions or status not in transitions.get(old_status, set()):
            _log("update_transcript", 409, False, "INVALID_TRANSITION")
            return _err(
                "INVALID_TRANSITION",
                "Requested status change is not allowed by lifecycle rules.",
                from_status=old_status,
                to_status=status,
                rule="transcripts.status transitions: active→superseded/deleted, superseded→deleted, deleted→(none)"
            )
        row["status"] = status

    # Mutability: allow source to be updated but enforce enum if it matches schema's known values; otherwise reject.
    if source is not None:
        allowed_source = {"youtube_transcript_api", "scraped", "unknown"}
        # schema enum is strict; accept only these
        if source not in allowed_source:
            _log("update_transcript", 400, False, "VALIDATION_ERROR source enum")
            return _err("VALIDATION_ERROR", "source must be one of: youtube_transcript_api, scraped, unknown", field="source")
        row["source"] = source

    if is_generated is not None:
        row["is_generated"] = is_generated

    row["updated_at"] = _now_iso()

    transcripts[t_idx] = row
    _save("transcripts.json", transcripts)

    _log("update_transcript", 200, True, None)
    return {"transcript": row}
